
import type { Image } from './Image.js';
import type { PublicPaymentLink } from './PublicPaymentLink.js';
import type { PublicResolvedLineItemInfo } from './PublicResolvedLineItemInfo.js';

export type PublicPaymentLinkResult = { /** The theme a checkout opened from this link uses: your checkout branding settings, with the link's own `theme` over them. Use it to style a page that leads to the checkout. `payment_link.theme` is the link's own theme alone. Omitted when neither sets a value. */ "checkout_theme"?: { "accent_color"?: string; "primary_color"?: string; "title"?: string; }; "is_sold_out"?: boolean; "merchant_logo"?: Image; "merchant_name"?: string; "payment_link": PublicPaymentLink; /** Whole-number quantity; fractional quantities are not supported. Format: int32. */ "remaining_quantity"?: number; "resolution_context": string; /** RFC3339 timestamp. Format: date-time. */ "resolution_context_expires_at": string; /** RFC3339 timestamp. Format: date-time. */ "resolution_context_start_deadline_at": string; "resolved_line_items"?: Array<PublicResolvedLineItemInfo>; /** Present for active plan-backed payment links when authoritative subscription terms are available. */ "subscription_preview"?: { "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** Minimum contract term in months, when configured. Format: int32. */ "contract_term_months"?: number; /** Early termination fee, when configured. */ "early_termination_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Plan image shown to the buyer, when configured. */ "plan_image"?: { "alt"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Format: int32. */ "height": number; "url": string; /** Format: int32. */ "width": number; }; /** Plan name shown to the buyer. */ "plan_name": string; /** Recurring total for one billing interval, including line quantities and resolved modifiers. */ "recurring_total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Setup fee added to the first amount due, when configured. */ "setup_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Number of trial days before the first recurring charge, when configured. Format: int32. */ "trial_period_days"?: number; }; };
